#define main e97_original_main
#include "evaluate.cpp"
#undef main
#include <faiss/IndexFlat.h>
const float* diagnosis_base=nullptr;
size_t diagnosis_dim=0;
int main(int argc,char**argv){try{threads();require(argc==3,"counts config output");auto c=read_json(argv[1]);fs::path out=argv[2];fs::create_directories(out);auto idx=load_nsg(c["index"]);idx->acsg.search_L=1250;size_t n=10000,d=idx->d;diagnosis_base=dynamic_cast<faiss::IndexFlat*>(idx->storage)->get_xb();diagnosis_dim=d;Fvecs fq(c["queries"]);std::vector<float> q(n*d);for(size_t i=0;i<n;++i)std::copy(fq.row(i),fq.row(i)+d,q.data()+i*d);Router router(c["soft"],d,c["router"].get<std::string>());router.counting(true);Worker w(*idx);Batch b(n,100);CountParam hc{};auto t=Clock::now();w.run("GT10-soft-t1",&router,nullptr,hc,q,d,b,true);double sec=seconds(t);save_batch(out,b,true);write_json(out/"measurement_done.json",{{"search_calls",n},{"seconds",sec}});fs::path ref=fs::path(c["e97_results"].get<std::string>())/"k100/GT10-soft-t1_L1250";require(b.ids==read_raw<int32_t>(ref/"ids.i32"),"ID parity");auto dist=read_raw<float>(ref/"distances.f32");require(!memcmp(dist.data(),b.dist.data(),dist.size()*4),"distance parity");require(b.entries==read_raw<int32_t>(ref/"entry_ids.i32"),"entry parity");require(b.route_ndc==read_raw<uint64_t>(ref/"route_ndc.u64"),"route NDC parity");require(b.graph_ndc==read_raw<uint64_t>(ref/"graph_ndc.u64"),"graph NDC parity");save_batch(out,b,true);write_json(out/"complete.json",{{"status","PASS"},{"search_calls",n},{"seconds_not_plain",sec},{"per_query_ndc_bit_output_parity",true},{"threads",process_threads()},{"cpu",15}});return 0;}catch(const std::exception&e){std::cerr<<e.what()<<std::endl;return 1;}}
